using System;
using System.Collections.Generic;
using Framework.Entities.Roles.Controllers;
using Framework.Entities.Roles.Enums;
using Framework.Entities.Roles.Functions;
using Framework.Events.Core;
using Framework.Events.Defines;

namespace Framework.Entities.Roles.Components
{
    /// <summary>
    /// 按持有者击败的怪物数量计算期限。效果结束时，调用 Dispose 清理订阅。
    /// 只监听 OnKill，不同时监听 OnMonsterDead，避免一次死亡扣两次。
    /// </summary>
    public sealed class KillCountLifetime : IDisposable
    {
        private readonly RoleController _holder;

        // Action 保存一个无参数方法，在效果到期时调用它。
        private readonly Action _onExpired;

        // HashSet 记录已经计数的怪物，同一个怪物不会重复加入。
        private readonly HashSet<RoleController> _countedTargets = new HashSet<RoleController>();
        private EventRegisterResult _registration;
        private bool _disposed;
        public int remainingKills { get; private set; }

        public KillCountLifetime(RoleController holder, EventDispatcher dispatcher, int killLimit, Action onExpired)
        {
            _holder = holder;
            _onExpired = onExpired;
            Refresh(killLimit);
            // 团队事件接口订阅击杀通知，返回的注册对象用于注销。
            _registration = dispatcher.Register<GlobalEvents.GamePlay.OnKill>(OnKill);
            _holder.OnStartDeathEvt += Expire;
        }

        /// <summary>重新设置剩余次数，但保留已计数的怪物，避免刷新后重复计数。</summary>
        public void Refresh(int killLimit)
        {
            if (_disposed)
            {
                return;
            }

            remainingKills = Math.Max(1, killLimit);
        }

        private void OnKill(GlobalEvents.GamePlay.OnKill evt)
        {
            if (_disposed)
            {
                return;
            }

            if (_holder == null || _holder.isDead)
            {
                return;
            }

            if (evt.killer != _holder)
            {
                return;
            }

            var target = evt.target as MonsterController;
            if (target == null || !target.isDead)
            {
                return;
            }

            var relation = target.entity.entityGroup.GetRelation(_holder.entity.entityGroup);
            if (relation != EntityGroupRelationEnum.Enemy)
            {
                return;
            }

            var isNewTarget = _countedTargets.Add(target);
            if (!isNewTarget)
            {
                return;
            }

            remainingKills -= 1;
            if (remainingKills == 0)
            {
                Expire();
            }
        }

        private void Expire()
        {
            if (_disposed)
            {
                return;
            }

            // 先取消订阅，再通知效果到期，避免回调期间再次处理事件。
            Dispose();
            if (_onExpired != null)
            {
                _onExpired.Invoke();
            }
        }

        /// <summary>IDisposable 约定的清理方法；重复调用也不会重复注销。</summary>
        public void Dispose()
        {
            if (_disposed)
            {
                return;
            }

            _disposed = true;
            _registration.Destroy();
            if (_holder != null)
            {
                _holder.OnStartDeathEvt -= Expire;
            }

            _countedTargets.Clear();
        }
    }
}

