using System;
using Framework.Entities.Buffs;
using Framework.Entities.StatsModule;
using Framework.Expressions;
using Sirenix.OdinInspector;
using UnityEngine;
using Utilities;

namespace Scripts.BuffModules
{
    [Serializable]
    [Name("通用/属性修改")]
    public class StatModifyModule : BuffModule
    {
        [ValueDropdown(OdinUtil.GetStatName)] [LabelText("属性类型")] [SerializeField]
        private string _statVarName;

        [LabelText("参数")] [SerializeField] private ModifierParamTypeEnum _modifierParamType = ModifierParamTypeEnum.Gain;

        [LabelText("表达式")] [SerializeField] private string _expression;


        private StatModifier _statModifier;

        public override void OnInitialize()
        {
            base.OnInitialize();
            // 团队表达式系统读取 Buff 与角色上下文，计算配置中的属性修正值。
            ExpressionVariableContext expressionVariableContext = new ExpressionVariableContext();
            expressionVariableContext.Add(buff);
            expressionVariableContext.Add(role.gameObject);
            var value = Evaluator.EvaluateFloat(_expression, expressionVariableContext);
            if (value != 0)
                _statModifier = new StatModifier(value, _modifierParamType);
        }

        public override void OnStart()
        {
            base.OnStart();
            if (_statModifier != null)
            {
                role.stats.AddModifier(_statVarName, _statModifier);
            }
        }

        public override void OnEnd()
        {
            base.OnEnd();
            if (_statModifier != null)
            {
                // 仅移除本模块添加的修正，不影响其他增益。
                role.stats.RemoveModifier(_statVarName, _statModifier);
                _statModifier = null;
            }
        }
    }
}
